"use strict";(self.webpackChunkpsj_docs=self.webpackChunkpsj_docs||[]).push([[86804],{83513:(n,e,r)=>{r.r(e),r.d(e,{assets:()=>m,contentTitle:()=>s,default:()=>u,frontMatter:()=>a,metadata:()=>i,toc:()=>l});var t=r(74848),o=r(28453);const a={id:"v5-0-2",sidebar_label:"v5.0.2",title:"Release Note V5.0.2"},s=void 0,i={id:"release-notes/v5-0-2",title:"Release Note V5.0.2",description:"",source:"@site/i18n/ja/docusaurus-plugin-content-docs/current/release-notes/v5.0.2.md",sourceDirName:"release-notes",slug:"/release-notes/v5-0-2",permalink:"/ja/docs/5.1.0/release-notes/v5-0-2",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{id:"v5-0-2",sidebar_label:"v5.0.2",title:"Release Note V5.0.2"},sidebar:"intro",previous:{title:"v5.0.3",permalink:"/ja/docs/5.1.0/release-notes/v5-0-3"},next:{title:"v5.0.1",permalink:"/ja/docs/5.1.0/release-notes/v5-0-1"}},m={},l=[];function d(n){const e={code:"code",pre:"pre",...(0,o.R)(),...n.components};return(0,t.jsx)(e.pre,{children:(0,t.jsx)(e.code,{className:"language-markdown",children:'import Tabs from \'@theme/Tabs\';\r\nimport TabItem from \'@theme/TabItem\';\r\n\r\n:::tip[\u30a2\u30c3\u30d7\u30c7\u30fc\u30c8\u306e\u30cf\u30a4\u30e9\u30a4\u30c8]\r\n\u3053\u306e\u30ea\u30ea\u30fc\u30b9\u306f\u4e3b\u306b\u65b0\u3057\u3044 [PSJ-GUI](../psj-gui) \u3068 [PSJ-Utility](../psj-utility) \u306e\u6a5f\u80fd\u306b\u7126\u70b9\u3092\u5f53\u3066\u3066\u3044\u307e\u3059\u3002\u8a73\u7d30\u306f\u6b21\u306e\u901a\u308a\u3067\u3059\uff1a\r\n\r\n- PSJ-GUI \u306e\u30b3\u30de\u30f3\u30c9\uff08API\uff09\u304a\u3088\u3073 GUI \u30b3\u30de\u30f3\u30c9\u30d3\u30eb\u30c0\u30fc\u306e\u4f7f\u3044\u3084\u3059\u3055\u3092\u5411\u4e0a\u3055\u305b\u307e\u3057\u305f\u3002\r\n- \u7279\u306b PSJ \u30d5\u30a9\u30f3\u30c8\u3068 PSJMessageBox\u3068\u3044\u3063\u305f\u65b0\u3057\u3044 PSJ-GUI \u30b3\u30de\u30f3\u30c9\uff08API\uff09\u3092\u8ffd\u52a0\u3057\u307e\u3057\u305f\u3002\r\n- PSJ-GUI \u3068 PSJ-Utility \u5411\u3051\u306e\u65b0\u3057\u3044\u30c7\u30fc\u30bf\u578b\u3092\u8ffd\u52a0\u3057\u307e\u3057\u305f\u3002\r\n- PSJ-GUI \u3067\u4f7f\u7528\u3055\u308c\u308b\u5f15\u6570\u540d\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- PSJ-GUI\u3001GUI \u30b3\u30de\u30f3\u30c9\u30d3\u30eb\u30c0\u30fc\u306e\u30af\u30e9\u30c3\u30b7\u30e5\u554f\u984c\u3068\u3044\u304f\u3064\u304b\u306e\u7d30\u304b\u3044\u30d0\u30b0\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n\r\n:::\r\nimport ReactPlayer from "react-player/lazy";\r\n\r\n## \ud83d\ude80 \u65b0\u6a5f\u80fd\r\n\r\n### \ud83d\udce6 \u30c7\u30fc\u30bf\u578b\r\n\r\n- PSJ-Command:  \u65b0\u3057\u3044 Enum _[`DItemType`](../data-type/psj-command/DItem-types)_ \u578b\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n  <details>\r\n  <summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f DItemType \u306e\u4e00\u89a7</summary>\r\n\r\n  | INT \u8868\u8a18  | DITEM \u306e\u30bf\u30a4\u30d7         |\r\n  | ------------- | --------------------- |\r\n  | 2             | `JPT.DItemType.INST`  |\r\n\r\n  </details>\r\n\r\n- PSJ-GUI: PSJMessageBox \u3067\u4f7f\u7528\u3055\u308c\u308b\u65b0\u3057\u3044\u5217\u6319\u578b _[`msgbox_icon`](../data-type/psj-gui/psj-message-box/msgbox-icon-types)_\u3001_[`msgbox_buttons`](../data-type/psj-gui/psj-message-box/msgbox-button-types)_\u3001_[`msgbox_position`](../data-type/psj-gui/psj-message-box/msgbox-position-types)_ \u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n\r\n- PSJ-Utility: \r\n  - \u65b0\u3057\u3044 Enum _[`MsgBoxType`](../data-type/psj-utility/pre-utility/enumeration-types/msgbox-types)_ \u578b\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n    <details>\r\n    <summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f MsgBoxType \u306e\u4e00\u89a7</summary>\r\n\r\n    | ID  | MSGBOX \u306e\u30bf\u30a4\u30d7                               |\r\n    | --- | ----------------------------------------- |\r\n    | 8   | `JPT.MsgBoxType.MB_CRITICAL_OK`           |\r\n\r\n    </details>\r\n\r\n  - API \u30b3\u30de\u30f3\u30c9 `JPT.DisableMessageBox()` \u306e\u65b0\u3057\u3044 Enum _[`MessageBoxOptionType`](../data-type/psj-utility/pre-utility/enumeration-types/msgbox-option-types)_ \u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\uff1a\r\n\r\n    <details>\r\n    <summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f MessageBoxOptionType \u306e\u4e00\u89a7</summary>\r\n\r\n    | ID  | MSGBOX \u30aa\u30d7\u30b7\u30e7\u30f3\u306e\u30bf\u30a4\u30d7                        |\r\n    | --- | ----------------------------------------- |\r\n    | 1   | `JPT.MsgBoxOptionType.MB_OPTION_OK`       |\r\n    | 2   | `JPT.MsgBoxOptionType.MB_OPTION_CANCEL`   |\r\n    | 6   | `JPT.MsgBoxOptionType.MB_OPTION_YES`      |\r\n    | 7   | `JPT.MsgBoxOptionType.MB_OPTION_NO`       |        \r\n\r\n    </details>\r\n\r\n### \ud83d\udee0 PSJ-Utility\r\n\r\n#### \ud83d\udcdd API\r\n\r\n\u30c7\u30fc\u30bf\u30d9\u30fc\u30b9\u30af\u30a8\u30ea\u306b\u95a2\u9023\u3059\u308b3\u3064\u306e\u65b0\u3057\u3044 API \u30b3\u30de\u30f3\u30c9\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\uff1a\r\n\r\n<details>\r\n\r\n<summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f\u30b3\u30de\u30f3\u30c9</summary>\r\n\r\n- `JPT.GetAllByTableTypeID()`: _[DTableType](../data-type/psj-utility/pre-utility/enumeration-types/dtable-types)_ \u3092\u5165\u529b\u3057\u3066\u3059\u3079\u3066\u306e\u30a8\u30f3\u30c6\u30a3\u30c6\u30a3\u306e\u60c5\u5831\u3092\u53d6\u5f97\u3057\u307e\u3059\u3002\r\n- `JPT.GetOutputLog()`: Output \u30a6\u30a3\u30f3\u30c9\u30a6\u306b\u5b58\u5728\u3059\u308b\u30c6\u30ad\u30b9\u30c8\u3092\u53d6\u5f97\u3057\u307e\u3059\u3002\r\n- `JPT.DisableMessageBox()`: \u753b\u9762\u4e0a\u306e\u30dd\u30c3\u30d7\u30a2\u30c3\u30d7\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u3092\u7121\u52b9\u306b\u3057\u3001\u30c7\u30d5\u30a9\u30eb\u30c8\u5024\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\r\n\r\n</details>\r\n\r\n- \u307e\u305f\u3001\u3044\u304f\u3064\u304b\u306e\u30b3\u30de\u30f3\u30c9\u304c\u4ee5\u4e0b\u306e\u3088\u3046\u306b\u4fee\u6b63\u3055\u308c\u3066\u3044\u307e\u3059\uff1a\r\n\r\n<details>\r\n<summary>\u5909\u66f4\u304a\u3088\u3073\u4fee\u6b63\u3055\u308c\u305f\u30b3\u30de\u30f3\u30c9\u306e\u4e00\u89a7</summary>\r\n\r\n- `JPT.DisableAnimation()`: \u30b3\u30de\u30f3\u30c9\u304c\u56de\u8ee2\u30d3\u30e5\u30fc\u3092\u30ad\u30e3\u30d7\u30c1\u30e3\u3067\u304d\u308b\u3088\u3046\u306b\u4fee\u6b63\u3055\u308c\u307e\u3057\u305f\u3002\r\n\r\n</details>\r\n\r\n### \ud83d\udcd0 PSJ-GUI\r\n\r\n#### \ud83d\udccf GUI \u30b3\u30de\u30f3\u30c9\u30d3\u30eb\u30c0\u30fc\r\n\r\n- Tool Box \u30b3\u30f3\u30dd\u30fc\u30cd\u30f3\u30c8\uff08[TabWnd](../gui-command-builder/tab-window)\u3001[Label](../gui-command-builder/label)\u3001[TextBox](../gui-command-builder/text-box)\u3001[RichEditCtrl](../gui-command-builder/rich-edit-control)\u3001[ComboBox](../gui-command-builder/combo-box)\u3001[ListBox](../gui-command-builder/list-box)\u3001[CheckBox](../gui-command-builder/check-box)\u3001[RadioButton](../gui-command-builder/radio-button)\u3001[Button](../gui-command-builder/button)\u3001[ImageCtrl](../gui-command-builder/image-control)\u3001[SliderBar](../gui-command-builder/slider-bar)\u3001[Table](../gui-command-builder/table)\u3001[PageCtrl](../gui-command-builder/pages-control)\uff09\u306e\u5e45/\u9ad8\u3055\u30d7\u30ed\u30d1\u30c6\u30a3\u304c "Size" \u30b5\u30d6\u30a2\u30bb\u30f3\u30d6\u30ea \u30d5\u30a9\u30eb\u30c0\u306b\u914d\u7f6e\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![Width/Height](../assets/GUI_CommandBuilder_Component_Label_V5.0.2.png)\r\n- Label \u30b3\u30f3\u30dd\u30fc\u30cd\u30f3\u30c8\u306e H.\u914d\u7f6e/V.\u914d\u7f6e\u304c "Alignment" \u30b5\u30d6\u30a2\u30bb\u30f3\u30d6\u30ea \u30d5\u30a9\u30eb\u30c0\u306b\u914d\u7f6e\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![H.Alignment/V.Alignment](../assets/GUI_CommandBuilder_Component_Label2_V5.0.2.png)\r\n- [TextBox](../gui-command-builder/text-box) \u306e\u8272\u3084\u30d5\u30a9\u30f3\u30c8\u30d7\u30ed\u30d1\u30c6\u30a3\u3092\u5909\u66f4\u3059\u308b\u65b0\u3057\u3044\u30aa\u30d7\u30b7\u30e7\u30f3\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![TextBox](../assets/GUI_CommandBuilder_Component_TextBox_V5.0.2.png)\r\n- [Button](../gui-command-builder/button) \u306e\u8272\u3084\u30d5\u30a9\u30f3\u30c8\u30d7\u30ed\u30d1\u30c6\u30a3\u3092\u5909\u66f4\u3059\u308b\u65b0\u3057\u3044\u30aa\u30d7\u30b7\u30e7\u30f3\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![Button](../assets/GUI_CommandBuilder_Component_Button_V5.0.2.png)\r\n- [PageCtrl](../gui-command-builder/pages-control) \u306e\u30ca\u30d3\u30b2\u30fc\u30bf\u30d7\u30ed\u30d1\u30c6\u30a3\uff08HighLight Color \u3068 Separator\uff09\u3092\u5909\u66f4\u3059\u308b\u65b0\u3057\u3044\u30aa\u30d7\u30b7\u30e7\u30f3\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![PagesCtrl](../assets/GUI_CommandBuilder_Component_PageCtrl_V5.0.2.png)\r\n- [PageItem](../gui-command-builder/page-item) \u306e\u8272\u3084\u30d5\u30a9\u30f3\u30c8\u30d7\u30ed\u30d1\u30c6\u30a3\u3092\u5909\u66f4\u3059\u308b\u65b0\u3057\u3044\u30aa\u30d7\u30b7\u30e7\u30f3\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\u3002\r\n  ![PageItem](../assets/GUI_CommandBuilder_Component_PageItem_V5.0.2.png)\r\n- [Separator](../gui-command-builder/separator) \u306b\u540d\u524d\u30d7\u30ed\u30d1\u30c6\u30a3\u3092\u8ffd\u52a0\u3057\u3066 Separator \u306e\u540d\u524d\u3092\u5236\u5fa1\u3067\u304d\u308b\u3088\u3046\u306b\u3057\u307e\u3057\u305f\u3002\r\n  ![ShortcutKey](../assets/GUI_CommandBuilder_Separator_V5.0.2.png)\r\n- \u30c6\u30fc\u30d6\u30eb\u64cd\u4f5c\u6642\u306eCopy/Cut\u304a\u3088\u3073Paste\u306e\u30b7\u30e7\u30fc\u30c8\u30ab\u30c3\u30c8\u30ad\u30fc\u3092\u30b5\u30dd\u30fc\u30c8\u3057\u307e\u3057\u305f\u3002\r\n  ![ShortcutKey](../assets/GUI_CommandBuilder_ShortcutKey_V5.0.2.png)\r\n\r\n#### \ud83d\udcdd API\r\n\r\n- \u4e00\u90e8\u306e\u30b3\u30de\u30f3\u30c9\u306e\u5f15\u6570\u540d\u304c\u7d71\u4e00\u306e\u305f\u3081\u306b\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\uff08\u65b0\u3057\u3044\u5f15\u6570\u540d\u306e\u30b3\u30fc\u30c9\u3092\u66f4\u65b0\u3057\u3066\u304f\u3060\u3055\u3044\uff09\u3002\r\n\r\n<details>\r\n\r\n<summary>\u5909\u66f4\u3055\u308c\u305f\u5f15\u6570\u540d\u306e\u4e00\u89a7</summary>\r\n\r\n| \u30b3\u30f3\u30dd\u30fc\u30cd\u30f3\u30c8 \u30b0\u30eb\u30fc\u30d7 | \u65e7\u5f15\u6570\u540d | \u65b0\u5f15\u6570\u540d | \u65b0\u3057\u3044\u5f15\u6570\u540d\u306e\u4f8b                                 |\r\n| --------------- | ----------------- | ----------------- | ------------------------------------------------------------ |\r\n| TABLE           | cell_row_id       | row               | dlg.get_cell_value(<strong>row</strong>=0,col=0\u2026)            |\r\n| TABLE           | cell_column_id    | col               | dlg.get_cell_value(row=0,<strong>col</strong>=0\u2026)            |\r\n\r\n</details>\r\n\r\n- \u307e\u305f\u3001\u4ee5\u4e0b\u306e\u3088\u3046\u306b\u4e00\u90e8\u306e\u30b3\u30de\u30f3\u30c9\u304c\u8ffd\u52a0\u304a\u3088\u3073\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\uff1a\r\n\r\n<details>\r\n<summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f\u30b3\u30de\u30f3\u30c9\u306e\u4e00\u89a7</summary>\r\n\r\n- `PSJMessageBox()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u306e\u30e1\u30bd\u30c3\u30c9\u3092\u6307\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.set_caption()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u306e\u30ad\u30e3\u30d7\u30b7\u30e7\u30f3\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.set_header()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u306e\u30d8\u30c3\u30c0\u30fc\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.set_icon()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u3067\u4f7f\u7528\u3059\u308b\u30a2\u30a4\u30b3\u30f3\u306e\u30bf\u30a4\u30d7\u3092\u6307\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.set_message()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u306e\u30e1\u30c3\u30bb\u30fc\u30b8\u30b3\u30f3\u30c6\u30f3\u30c4\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.enable_checkbox()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u306b\u30c1\u30a7\u30c3\u30af\u30dc\u30c3\u30af\u30b9\u3092\u6307\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.set_buttons()`: PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u3067\u3001\u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u3067\u30b5\u30dd\u30fc\u30c8\u3055\u308c\u308b\u5229\u7528\u53ef\u80fd\u306a\u30dc\u30bf\u30f3\u306e\u30bb\u30c3\u30c8\u3092\u6307\u5b9a\u3057\u307e\u3059\u3002\r\n- `msgbox.add_button()`: \u30e6\u30fc\u30b6\u30fc\u304c\u5b9a\u7fa9\u3057\u305f\u30dc\u30bf\u30f3\u540d\u3067\u30dc\u30bf\u30f3\u3092\u8ffd\u52a0\u3059\u308b PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u306e\u30b3\u30de\u30f3\u30c9\u3067\u3059\u3002\r\n- `msgbox.show()`: \u30e1\u30c3\u30bb\u30fc\u30b8\u30dc\u30c3\u30af\u30b9\u3092\u8868\u793a\u3059\u308b PSJMessageBox \u30af\u30e9\u30b9\u306e\u30a4\u30f3\u30b9\u30bf\u30f3\u30b9\u306e\u30b3\u30de\u30f3\u30c9\u3067\u3059\u3002\r\n- `dlg.set_item_font()`: \u30b3\u30f3\u30dd\u30fc\u30cd\u30f3\u30c8\u5185\u306e\u30c6\u30ad\u30b9\u30c8\u306b\u30d5\u30a9\u30f3\u30c8\u30d7\u30ed\u30d1\u30c6\u30a3\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\r\n- `dlg.get_cell_label()`: \u30c6\u30fc\u30d6\u30eb\u5185\u306e\u30dc\u30bf\u30f3\u30bb\u30eb\u3001\u30c1\u30a7\u30c3\u30af\u30dc\u30c3\u30af\u30b9\u30bb\u30eb\u3001\u307e\u305f\u306f\u30b3\u30f3\u30dc\u30dc\u30c3\u30af\u30b9\u30bb\u30eb\u306e\u30e9\u30d9\u30eb\u3092\u53d6\u5f97\u3057\u307e\u3059\u3002\r\n\r\n</details>\r\n\r\n<details>\r\n\r\n<summary>\u5909\u66f4\u307e\u305f\u306f\u4fee\u6b63\u3055\u308c\u305f\u30b3\u30de\u30f3\u30c9\u306e\u4e00\u89a7</summary>\r\n\r\n- `dlg.add_pagesctrl()`: \u30bb\u30d1\u30ec\u30fc\u30bf\u5883\u754c\u306e\u30b9\u30c6\u30fc\u30b8\u3092\u6307\u5b9a\u3059\u308b\u305f\u3081\u306e\u65b0\u3057\u3044\u5f15\u6570 `show_separator` \u304a\u3088\u3073 `sel_color` \u3092\u8ffd\u52a0\u3057\u3001PageItem \u3092\u9078\u629e\u3059\u308b\u969b\u306e\u30cf\u30a4\u30e9\u30a4\u30c8\u30ab\u30e9\u30fc\u3092\u6307\u5b9a\u3057\u307e\u3059\u3002\r\n- `dlg.add_pageitem()`: \u30c6\u30ad\u30b9\u30c8\u30ab\u30e9\u30fc\u3068\u80cc\u666f\u8272\u306e PageItem \u306e\u30c6\u30ad\u30b9\u30c8\u30ab\u30e9\u30fc\u3068\u80cc\u666f\u8272\u3092\u6307\u5b9a\u3059\u308b\u305f\u3081\u306e\u65b0\u3057\u3044\u5f15\u6570 `text_color` \u3068 `bk_color` \u3092\u8ffd\u52a0\u3057\u307e\u3059\u3002\r\n- `dlg.add_textbox()`: \u30c6\u30ad\u30b9\u30c8\u30dc\u30c3\u30af\u30b9\u306e\u30c6\u30ad\u30b9\u30c8\u30ab\u30e9\u30fc\u3068\u80cc\u666f\u8272\u3092\u6307\u5b9a\u3059\u308b\u305f\u3081\u306e\u65b0\u3057\u3044\u5f15\u6570 `text_color` \u3068 `bk_color` \u3092\u8ffd\u52a0\u3057\u307e\u3059\u3002\r\n- `dlg.add_button()`: \u30dc\u30bf\u30f3\u306e\u30c6\u30ad\u30b9\u30c8\u30ab\u30e9\u30fc\u3068\u80cc\u666f\u8272\u3092\u6307\u5b9a\u3059\u308b\u305f\u3081\u306e\u65b0\u3057\u3044\u5f15\u6570 `text_color` \u3068 `bk_color` \u3092\u8ffd\u52a0\u3057\u307e\u3059\u3002\r\n- `dlg.insert_table_row()`: \u5f15\u6570 `position` \u306e\u4f7f\u7528\u610f\u5473\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\u3053\u306e\u5f15\u6570\u304c\u6307\u5b9a\u3055\u308c\u3066\u3044\u308b\u5834\u5408\u3001\u884c\u306f\u5165\u529b\u3055\u308c\u305f\u4f4d\u7f6e\u306e\u524d\u306b\u633f\u5165\u3055\u308c\u307e\u3059\uff08position-1\uff09\u3002\u6307\u5b9a\u3055\u308c\u3066\u3044\u306a\u3044\u5834\u5408\u306f\u3001\u884c\u306f\u30c6\u30fc\u30d6\u30eb\u306e\u672b\u5c3e\u306b\u633f\u5165\u3055\u308c\u307e\u3059\u3002\r\n- `dlg.set_cell_value()`: \u5f15\u6570\u540d\u3092\u7d71\u4e00\u3059\u308b\u305f\u3081\u3001cell_row_id/cell_column_id \u3092 row/col \u306b\u5909\u66f4\u3057\u307e\u3057\u305f\u3002\r\n- `dlg.get_cell_value ()`: \u5f15\u6570\u540d\u3092\u7d71\u4e00\u3059\u308b\u305f\u3081\u3001cell_row_id/cell_column_id \u3092 row/col \u306b\u5909\u66f4\u3057\u307e\u3057\u305f\u3002\r\n\r\n</details>\r\n\r\n### \u2699 \u30de\u30af\u30ed\r\n\r\n- \u30dd\u30b9\u30c8\u51e6\u7406\u304a\u3088\u3073\u30c6\u30f3\u30d7\u30ec\u30fc\u30c8\u306e\u5229\u7528\u306b\u95a2\u9023\u3059\u308b\u30de\u30af\u30ed\u304c\u8ffd\u52a0\u3055\u308c\u307e\u3057\u305f\uff1a\r\n\r\n<details>\r\n\r\n<summary>\u65b0\u305f\u306b\u8ffd\u52a0\u3055\u308c\u305f\u30de\u30af\u30ed\u306e\u4e00\u89a7</summary>\r\n\r\n- `SetHiddingElementFactor`: \u975e\u8868\u793a\u8981\u7d20\u30d5\u30a1\u30af\u30bf\u30fc\u3092\u8a2d\u5b9a\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncPlay`: \u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u3092\u518d\u751f\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncPause`: \u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u306e\u4e00\u6642\u505c\u6b62\u3092\u884c\u3046\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncPrev`: \u524d\u306e\u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u3092\u518d\u751f\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncNext`: \u6b21\u306e\u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u3092\u518d\u751f\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncFirst`: \u6700\u521d\u306e\u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u3092\u518d\u751f\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationIncLast`: \u6700\u5f8c\u306e\u30a2\u30cb\u30e1\u30fc\u30b7\u30e7\u30f3\u3092\u518d\u751f\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdPostOptimizationAnimationExportMovie`: \u30e0\u30fc\u30d3\u30fc\u3092\u30a8\u30af\u30b9\u30dd\u30fc\u30c8\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `ViewSelectMethod`: \u4e2d\u5fc3\u7bc0\u70b9\u30aa\u30d7\u30b7\u30e7\u30f3\u3092\u30aa\u30f3/\u30aa\u30d5\u306b\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `ViewCappingOriginalShape`: \u30ad\u30e3\u30c3\u30d7\u5143\u306e\u5f62\u72b6\u3092\u30aa\u30f3/\u30aa\u30d5\u306b\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdMarkupSearchNodeFromPoint`: \u6700\u3082\u8fd1\u3044\u7bc0\u70b9\u3092\u691c\u7d22\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdMarkupSearchNodesFromMultiPoints`: CSV \u304b\u3089\u4f4d\u7f6e\u3054\u3068\u306e\u6700\u3082\u8fd1\u3044\u7bc0\u70b9\u3092\u691c\u7d22\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdMarkupSearchElementsFromPoint`: \u6700\u3082\u8fd1\u3044\u8981\u7d20\u3092\u691c\u7d22\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n- `CmdMarkupSearchElementsFromMultiPoints`: CSV \u304b\u3089\u4f4d\u7f6e\u3054\u3068\u306e\u6700\u3082\u8fd1\u3044\u8981\u7d20\u3092\u691c\u7d22\u3059\u308b\u30de\u30af\u30ed\u3067\u3059\u3002\r\n\r\n</details>\r\n\r\n- \u307e\u305f\u3001\u3044\u304f\u3064\u304b\u306e\u30de\u30af\u30ed\u304c\u4ee5\u4e0b\u306e\u3088\u3046\u306b\u4fee\u6b63\u3055\u308c\u3066\u3044\u307e\u3059\uff1a\r\n\r\n<details>\r\n<summary>\u5909\u66f4\u304a\u3088\u3073\u4fee\u6b63\u3055\u308c\u305f\u30de\u30af\u30ed\u306e\u4e00\u89a7</summary>\r\n\r\n- `ViewSectionBox()`: \u30b3\u30de\u30f3\u30c9\u3092\u4fee\u6b63\u3057\u3066\u56de\u8ee2\u30d3\u30e5\u30fc\u3092\u30ad\u30e3\u30d7\u30c1\u30e3\u3067\u304d\u308b\u3088\u3046\u306b\u3057\u307e\u3057\u305f\u3002\r\n- `CmdShowPostDeformation()`: \u53ef\u8aad\u6027\u306e\u305f\u3081\u3001\u30de\u30af\u30ed\u5f15\u6570\u5185\u306e\u69cb\u9020\u7684\u7d50\u5408\u3092{}\u3067\u56f2\u3093\u3067\u3044\u307e\u3059\u3002\u30b3\u30fc\u30c9\u3092\u66f4\u65b0\u3057\u3066\u304f\u3060\u3055\u3044\u3002\r\n\r\n</details>\r\n\r\n### \ud83d\ude85 \u30b5\u30f3\u30d7\u30eb\r\n\r\n- \u65b0\u3057\u3044 PSJ-Utility \u30b3\u30de\u30f3\u30c9 `JPT.GetOutputLog()` \u3092\u4f7f\u7528\u3057\u305f\u30c1\u30e5\u30fc\u30c8\u30ea\u30a2\u30eb _[Get output, macro and Python log](../tutorials/basic/get-output-macro-and-python-log)_ \u3092\u66f4\u65b0\u3057\u307e\u3057\u305f\u3002\r\n\r\n#### \ud83d\udcdd \u305d\u306e\u4ed6\r\n\r\n- 2\u3064\u306e\u30b3\u30de\u30f3\u30c9 `dlg.set_item_font()` \u304a\u3088\u3073 `dlg.get_item_font()` \u306e\u5f15\u6570\u540d\u304c\u5909\u66f4\u3055\u308c\u305f\u305f\u3081\u3001PSJ GUI \u30b3\u30de\u30f3\u30c9\u306e\u30b5\u30f3\u30d7\u30eb\u30b3\u30fc\u30c9\u3092\u66f4\u65b0\u3057\u307e\u3057\u305f\u3002\r\n\r\n## \ud83d\udc1b \u30d0\u30b0\u4fee\u6b63\r\n\r\n### \u2318 PSJ-Command\r\n\r\n- Python \u30a6\u30a3\u30f3\u30c9\u30a6\u3067 PSJ-Command Force-General \u3092\u51fa\u529b\u3059\u308b\u3068\u304d\u306b [strName](../psj-command/boundary-conditions/BoundaryConditions.Force.General#strname) \u30ad\u30fc\u30ef\u30fc\u30c9\u5f15\u6570\u304c\u6b20\u843d\u3057\u3066\u3044\u305f\u554f\u984c\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- GUI \u3068 API \u30b3\u30fc\u30c9\u64cd\u4f5c\u9593\u3067\u8ffd\u52a0\u3055\u308c\u305f\u7d20\u6750 ID \u304c\u4e00\u81f4\u3057\u306a\u3044\u554f\u984c\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- [BodyCut-XXYYOnOnePoint](../psj-command/geometry/Geometry.BodyCut.XXYYOnOnePoint) \u306e PSJ-Command \u751f\u6210\u6642\u306b\u30a8\u30e9\u30fc\u304c\u767a\u751f\u3059\u308b\u4e0d\u5177\u5408\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n\r\n### \ud83d\udcd0 PSJ-GUI\r\n\r\n#### \ud83d\udcdd API\r\n\r\n- GUI \u30b3\u30de\u30f3\u30c9\u30d3\u30eb\u30c0\u30fc\u304b\u3089\u30a8\u30af\u30b9\u30dd\u30fc\u30c8\u3055\u308c\u305f API \u30b3\u30fc\u30c9\u3092\u5b9f\u884c\u3059\u308b\u3068\u3001\u30bb\u30ec\u30af\u30bf\u304c\u8868\u793a\u3055\u308c\u306a\u3044\u4e0d\u5177\u5408\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- \u30c6\u30fc\u30d6\u30eb\u306e\u30e1\u30cb\u30e5\u30fc\u3067\u30af\u30ea\u30a2\u3001\u30ab\u30c3\u30c8\u30c7\u30fc\u30bf\u3001\u884c\u633f\u5165\u30aa\u30d7\u30b7\u30e7\u30f3\u3092\u4f7f\u7528\u5f8c\u3001\u30d5\u30a1\u30a4\u30eb\u304b\u3089\u30c7\u30fc\u30bf\u3092\u518d\u8aad\u307f\u8fbc\u307f\u3067\u304d\u306a\u3044\u4e0d\u5177\u5408\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- \u30b9\u30d4\u30f3\u306e\u5024\u3092\u53d6\u5f97\u3067\u304d\u306a\u3044\u554f\u984c\u3092\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- \u30c6\u30fc\u30d6\u30eb\u306e Integer \u5217\u306b\u5024\u3092\u8a2d\u5b9a\u3067\u304d\u306a\u3044\u554f\u984c\u3092 API \u30b3\u30de\u30f3\u30c9 `dlg.set_cell_value()` \u3067\u4fee\u6b63\u3057\u307e\u3057\u305f\u3002\r\n- API \u30b3\u30de\u30f3\u30c9 `dlg.set_slider_vertical()`\n'})})}function u(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,t.jsx)(e,{...n,children:(0,t.jsx)(d,{...n})}):d(n)}},28453:(n,e,r)=>{r.d(e,{R:()=>s,x:()=>i});var t=r(96540);const o={},a=t.createContext(o);function s(n){const e=t.useContext(a);return t.useMemo((function(){return"function"==typeof n?n(e):{...e,...n}}),[e,n])}function i(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(o):n.components||o:s(n.components),t.createElement(a.Provider,{value:e},n.children)}}}]);